#!/usr/bin/env python3
"""A small terminal flamegraph viewer compatible with the observed flamelens CLI.

This is an original reimplementation based on the documented/observed behavior of
./executable in this benchmark.  It intentionally uses only the Python standard
library so compile.sh can work offline.
"""
from __future__ import annotations

import errno
import math
import os
import re
import select
import shutil
import signal
import sys
import termios
import time
import tty
from collections import OrderedDict
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Tuple

VERSION = "0.3.1"
APP_VERSION = f"flamelens {VERSION}"
HEADER_VERSION = f"flamelens v{VERSION}"
FOOTER = " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [r: reset]"
NON_TTY_ERROR = 'Error: Os { code: 11, kind: WouldBlock, message: "Resource temporarily unavailable" }\n'


# ---------------------------------------------------------------------------
# Command-line parsing (manual, shaped to match the observed clap output)

class CliExit(Exception):
    def __init__(self, code: int, stdout: str = "", stderr: str = "") -> None:
        super().__init__(code)
        self.code = code
        self.stdout = stdout
        self.stderr = stderr


@dataclass
class Args:
    sorted: bool = False
    echo: bool = False
    debug: bool = False
    filename: Optional[str] = None


def help_text(prog: str) -> str:
    return (
        f"Usage: {prog} [OPTIONS] [FILENAME]\n\n"
        "Arguments:\n"
        "  [FILENAME]  Profile data filename\n\n"
        "Options:\n"
        "      --sorted   Whether to sort the stacks by time spent\n"
        "      --echo     Print data to stdout on exit. Useful when piping to other tools\n"
        "      --debug    Show debug info\n"
        "  -h, --help     Print help\n"
        "  -V, --version  Print version\n"
    )


def err_unexpected(prog: str, arg: str, after_filename_option: bool = False) -> str:
    tip = ""
    if arg.startswith("-"):
        tip = f"\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n"
    # clap occasionally uses this narrower usage after a filename followed by an
    # unknown option.  Reproduce the common observed shape.
    usage = f"Usage: {prog} <FILENAME|--sorted|--echo|--debug>" if after_filename_option and arg.startswith("--") else f"Usage: {prog} [OPTIONS] [FILENAME]"
    return f"error: unexpected argument '{arg}' found\n{tip}\n{usage}\n\nFor more information, try '--help'.\n"


def err_duplicate(prog: str, arg: str) -> str:
    return (
        f"error: the argument '{arg}' cannot be used multiple times\n\n"
        f"Usage: {prog} [OPTIONS] [FILENAME]\n\n"
        "For more information, try '--help'.\n"
    )


def err_unexpected_value(prog: str, opt: str, value: str) -> str:
    return (
        f"error: unexpected value '{value}' for '{opt}' found; no more were expected\n\n"
        f"Usage: {prog} {opt} [FILENAME]\n\n"
        "For more information, try '--help'.\n"
    )


def parse_args(argv: List[str]) -> Args:
    prog = os.path.basename(argv[0]) or "executable"
    out = Args()
    seen: set[str] = set()
    after_dd = False
    i = 1
    while i < len(argv):
        arg = argv[i]
        if not after_dd and arg == "--":
            after_dd = True
            i += 1
            continue

        if not after_dd and arg.startswith("--") and len(arg) > 2:
            opt, eq, value = arg.partition("=")
            if opt in ("--help", "--version", "--sorted", "--echo", "--debug"):
                if eq and opt in ("--sorted", "--echo", "--debug"):
                    raise CliExit(2, stderr=err_unexpected_value(prog, opt, value))
                if opt == "--help":
                    raise CliExit(0, stdout=help_text(prog))
                if opt == "--version":
                    raise CliExit(0, stdout=APP_VERSION + "\n")
                if opt in seen:
                    raise CliExit(2, stderr=err_duplicate(prog, opt))
                seen.add(opt)
                if opt == "--sorted":
                    out.sorted = True
                elif opt == "--echo":
                    out.echo = True
                elif opt == "--debug":
                    out.debug = True
                i += 1
                continue
            raise CliExit(2, stderr=err_unexpected(prog, arg, out.filename is not None))

        if not after_dd and arg.startswith("-") and arg != "-":
            # clap permits grouped short flags for h/V, and stops immediately on
            # help/version.  There are no short flags for sorted/echo/debug.
            if len(arg) >= 2:
                for ch in arg[1:]:
                    if ch == "h":
                        raise CliExit(0, stdout=help_text(prog))
                    if ch == "V":
                        raise CliExit(0, stdout=APP_VERSION + "\n")
                    raise CliExit(2, stderr=err_unexpected(prog, "-" + ch, out.filename is not None))
                i += 1
                continue

        # Positional filename.
        if out.filename is None:
            out.filename = arg
            i += 1
            continue
        raise CliExit(2, stderr=err_unexpected(prog, arg, False))
    return out


# ---------------------------------------------------------------------------
# Input and folded-stack parsing

@dataclass
class Node:
    name: str
    parent: Optional["Node"] = None
    value: int = 0
    children: "OrderedDict[str, Node]" = field(default_factory=OrderedDict)
    serial: int = 0

    def child(self, name: str, serial: int) -> "Node":
        if name not in self.children:
            self.children[name] = Node(name=name, parent=self, serial=serial)
        return self.children[name]

    def path(self) -> List["Node"]:
        n: Optional[Node] = self
        p: List[Node] = []
        while n is not None:
            p.append(n)
            n = n.parent
        p.reverse()
        return p


@dataclass
class StackRecord:
    frames: List[str]
    count: int


@dataclass
class Profile:
    root: Node
    records: List[StackRecord]
    node_serial: int


def parse_u64_decimal(s: str) -> Optional[int]:
    # Rust's integer FromStr accepts only decimal digits here (no whitespace,
    # signs, floats, tabs or CR).  Empty is invalid.
    if not s or not all("0" <= c <= "9" for c in s):
        return None
    try:
        return int(s, 10)
    except Exception:
        return None


def parse_folded(data: str) -> Profile:
    root = Node("all", None, 0, OrderedDict(), 0)
    records: List[StackRecord] = []
    serial = 1
    # Observed behavior matches splitting on LF only; a CR before the count makes
    # that count invalid.
    for line in data.split("\n"):
        if " " not in line:
            continue
        stack, count_s = line.rsplit(" ", 1)
        count = parse_u64_decimal(count_s)
        if count is None:
            continue
        frames = stack.split(";")
        records.append(StackRecord(frames, count))
        root.value += count
        node = root
        for frame in frames:
            if frame not in node.children:
                node.children[frame] = Node(name=frame, parent=node, serial=serial)
                serial += 1
            node = node.children[frame]
            node.value += count
    return Profile(root=root, records=records, node_serial=serial)


def rust_io_kind(e: OSError) -> str:
    mapping = {
        errno.ENOENT: "NotFound",
        errno.EISDIR: "IsADirectory",
        errno.EACCES: "PermissionDenied",
        errno.EPERM: "PermissionDenied",
        errno.ENOTDIR: "NotADirectory",
    }
    return mapping.get(getattr(e, "errno", None), "Other")


def panic_read_file(e: OSError) -> int:
    code = getattr(e, "errno", 0) or 0
    kind = rust_io_kind(e)
    msg = getattr(e, "strerror", None) or os.strerror(code) if code else str(e)
    # Rust's default panic includes a thread id.  It is process-specific in the
    # observed binary, so use this process id as a similarly varying integer.
    sys.stderr.write(
        f"\nthread 'main' ({os.getpid()}) panicked at src/main.rs:44:47:\n"
        f"Could not read file: Os {{ code: {code}, kind: {kind}, message: \"{msg}\" }}\n"
    )
    if os.environ.get("RUST_BACKTRACE"):
        sys.stderr.write("stack backtrace:\n")
        sys.stderr.write("note: Some details are omitted in this reimplementation\n")
    else:
        sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    return 101


def read_profile(args: Args) -> Tuple[str, str]:
    if args.filename is not None:
        try:
            with open(args.filename, "rb") as f:
                raw = f.read()
            try:
                data = raw.decode("utf-8")
            except UnicodeDecodeError as ue:
                # read_to_string would surface InvalidData; format it like the
                # same panic site.
                e = OSError(errno.EINVAL, "stream did not contain valid UTF-8")
                raise e from ue
            return data, args.filename
        except OSError as e:
            raise
    raw = sys.stdin.buffer.read()
    try:
        data = raw.decode("utf-8")
    except UnicodeDecodeError:
        data = raw.decode("utf-8", "replace")
    return data, "stdin"


# ---------------------------------------------------------------------------
# Rendering helpers

@dataclass
class Rect:
    node: Node
    x: int
    y_depth: int
    w: int


def display_width(s: str) -> int:
    # The benchmark inputs are overwhelmingly ASCII; for simple Unicode, count
    # codepoints.  This keeps truncation deterministic without external wcwidth.
    return len(s)


def trunc(s: str, width: int) -> str:
    if width <= 0:
        return ""
    return s[:width]


def put_text(line: List[str], start: int, text: str) -> None:
    if start >= len(line):
        return
    if start < 0:
        text = text[-start:]
        start = 0
    for i, ch in enumerate(text):
        pos = start + i
        if 0 <= pos < len(line):
            line[pos] = ch


def pct_str(num: int, den: int) -> str:
    if den == 0:
        return "NaN"
    return f"{(num * 100.0 / den):.2f}"


def child_list(node: Node, sorted_flag: bool) -> List[Node]:
    vals = list(node.children.values())
    if sorted_flag:
        vals.sort(key=lambda n: (-n.value, n.serial))
    return vals


def layout_subtree(node: Node, depth: int, x: int, w: int, sorted_flag: bool, rects: List[Rect]) -> None:
    if w <= 0:
        return
    rects.append(Rect(node, x, depth, w))
    children = child_list(node, sorted_flag)
    if not children or node.value <= 0:
        return
    cum = 0
    for c in children:
        # cumulative rounding gives stable full-width allocation, close to common
        # flamegraph renderers.
        sx = x + int(round(cum * w / node.value))
        cum += c.value
        ex = x + int(round(cum * w / node.value))
        cw = max(0, ex - sx)
        if cw <= 0:
            continue
        layout_subtree(c, depth + 1, sx, cw, sorted_flag, rects)


def compute_rects(root: Node, zoom: Node, width: int, sorted_flag: bool) -> List[Rect]:
    rects: List[Rect] = []
    if width <= 0:
        return rects
    # Ancestors of the zoomed node remain visible as full-width context rows.
    path = zoom.path()
    for depth, node in enumerate(path[:-1]):
        rects.append(Rect(node, 0, depth, width))
    layout_subtree(zoom, len(path) - 1, 0, width, sorted_flag, rects)
    return rects


def max_depth(rects: List[Rect]) -> int:
    if not rects:
        return 0
    return max(r.y_depth for r in rects)


def rect_for_node(rects: List[Rect], node: Node) -> Optional[Rect]:
    for r in rects:
        if r.node is node:
            return r
    return None


def node_detail(node: Node, root: Node, zoom: Node) -> str:
    s = f"{node.name} [{node.value} samples, {pct_str(node.value, root.value)}% of all"
    if zoom is not root:
        s += f", {pct_str(node.value, zoom.value)}% of zoomed"
    s += "]"
    return s


def separator(width: int, title: Optional[str] = None) -> str:
    if width <= 0:
        return ""
    if title:
        prefix = title + " "
        return (prefix + "─" * max(0, width - len(prefix)))[:width]
    return "─" * width


def header_line(width: int, source: str) -> str:
    line = [" "] * width
    put_text(line, 1, "[Flamegraph]")
    put_text(line, 14, "|")
    put_text(line, 16, "Top")
    version_start = max(0, width - len(HEADER_VERSION))
    put_text(line, version_start, HEADER_VERSION)
    left = 20
    right = version_start
    if right > left and width > left:
        avail = right - left
        shown = trunc(source, avail)
        start = left + math.ceil(max(0, avail - len(shown)) / 2)
        put_text(line, start, shown)
    return "".join(line)


# Flame-like colors.  Tmux capture strips these, while raw script captures still
# see broadly similar ANSI styling to the original.
PALETTE = [
    (214, 44, 10),
    (233, 128, 30),
    (244, 180, 43),
    (254, 229, 54),
    (220, 70, 20),
    (238, 150, 35),
]


def hash_color(name: str) -> Tuple[int, int, int]:
    h = 0
    for b in name.encode("utf-8", "replace"):
        h = ((h * 33) + b) & 0xFFFFFFFF
    return PALETTE[h % len(PALETTE)]


def colorize_frame(text: str, node: Node, selected: bool, match: bool, root: Node) -> str:
    if node is root:
        bg = (250, 250, 250)
        fg = (10, 10, 10)
    elif selected:
        bg = (250, 250, 250)
        fg = (10, 10, 10)
    elif match:
        bg = (120, 120, 250)
        fg = (10, 10, 10)
    else:
        bg = hash_color(node.name)
        # Dark red backgrounds used light text in the original.
        fg = (225, 225, 225) if sum(bg) < 300 else (10, 10, 10)
    return f"\x1b[38;2;{fg[0]};{fg[1]};{fg[2]};48;2;{bg[0]};{bg[1]};{bg[2]}m{text}\x1b[39;49m"


@dataclass
class UIState:
    profile: Profile
    source: str
    sorted: bool = False
    debug: bool = False
    selected: Node = field(init=False)
    zoom: Node = field(init=False)
    scroll: int = 0
    cursor_x: Optional[int] = None
    search_mode: bool = False
    search_input: str = ""
    match_query: Optional[str] = None
    match_regex: Optional[re.Pattern] = None
    match_nodes: List[Node] = field(default_factory=list)
    match_samples: int = 0
    info: Optional[str] = None

    def __post_init__(self) -> None:
        self.selected = self.profile.root
        self.zoom = self.profile.root

    @property
    def root(self) -> Node:
        return self.profile.root

    def current_rects(self, width: int) -> List[Rect]:
        return compute_rects(self.root, self.zoom, width, self.sorted)

    def ensure_selected_visible(self, rects: List[Rect], flame_rows: int) -> None:
        r = rect_for_node(rects, self.selected)
        if not r:
            self.selected = self.zoom
            r = rect_for_node(rects, self.selected)
        if not r or flame_rows <= 0:
            return
        max_scroll = max(0, max_depth(rects) - flame_rows + 1)
        if r.y_depth < self.scroll:
            self.scroll = r.y_depth
        elif r.y_depth >= self.scroll + flame_rows:
            self.scroll = r.y_depth - flame_rows + 1
        self.scroll = max(0, min(self.scroll, max_scroll))

    def visible_rows_count(self, height: int) -> Tuple[int, int, int]:
        # returns (flame_start_row_1based, flame_rows, bottom_start_row_1based)
        blocks = 1  # selected
        if self.search_mode or self.match_query is not None:
            blocks += 1
        if self.info:
            blocks += 1
        if self.debug:
            blocks += 1
        bottom_rows = blocks * 2 + 2  # blocks plus separator/footer
        header_rows = 3 if height >= 13 else 2
        flame_rows = max(0, height - header_rows - bottom_rows)
        flame_start = header_rows + 1
        bottom_start = header_rows + flame_rows + 1
        return flame_start, flame_rows, bottom_start

    def matching(self, node: Node) -> bool:
        return self.match_regex is not None and node in self.match_nodes

    def update_matches(self, query: str) -> None:
        self.info = None
        if query == "":
            self.match_query = None
            self.match_regex = None
            self.match_nodes = []
            self.match_samples = 0
            return
        try:
            rx = re.compile(query)
        except re.error:
            self.match_query = None
            self.match_regex = None
            self.match_nodes = []
            self.match_samples = 0
            self.info = f"Invalid regex: {query}"
            return
        self.match_query = query
        self.match_regex = rx
        rects = compute_rects(self.root, self.zoom, 100000, self.sorted)
        # preorder in visual order, excluding the artificial root "all".
        nodes: List[Node] = []
        seen: set[int] = set()
        for r in sorted(rects, key=lambda r: (r.y_depth, r.x, r.node.serial)):
            if r.node is self.root:
                continue
            if id(r.node) in seen:
                continue
            seen.add(id(r.node))
            if rx.search(r.node.name):
                nodes.append(r.node)
        self.match_nodes = nodes
        total = 0
        for rec in self.profile.records:
            if any(rx.search(frame) for frame in rec.frames):
                total += rec.count
        self.match_samples = total

    def next_match(self, backwards: bool = False) -> None:
        if not self.match_nodes:
            return
        try:
            idx = self.match_nodes.index(self.selected)
        except ValueError:
            # Observed N from a non-matching root is a no-op; n jumps to first.
            if backwards:
                return
            self.selected = self.match_nodes[0]
            return
        if backwards:
            if idx > 0:
                self.selected = self.match_nodes[idx - 1]
        else:
            if idx + 1 < len(self.match_nodes):
                self.selected = self.match_nodes[idx + 1]

    def reset_view(self) -> None:
        self.zoom = self.root
        self.selected = self.root
        self.scroll = 0
        self.cursor_x = None
        self.search_mode = False
        self.search_input = ""
        self.match_query = None
        self.match_regex = None
        self.match_nodes = []
        self.match_samples = 0
        self.info = None

    def set_zoom(self) -> None:
        self.zoom = self.selected
        self.scroll = 0
        self.cursor_x = None

    def clear_zoom(self) -> None:
        self.zoom = self.root
        self.scroll = 0
        self.cursor_x = None

    def navigate(self, key: str, width: int, height: int) -> None:
        rects = self.current_rects(width)
        flame_start, flame_rows, _ = self.visible_rows_count(height)
        if not rects:
            return
        self.ensure_selected_visible(rects, flame_rows)
        max_scroll = max(0, max_depth(rects) - flame_rows + 1)

        if key in ("f", "b", "g", "G"):
            step = max(1, flame_rows)
            if key == "f":
                self.scroll = min(max_scroll, self.scroll + step)
            elif key == "b":
                self.scroll = max(0, self.scroll - step)
            elif key == "g":
                self.scroll = 0
            elif key == "G":
                self.scroll = max_scroll
            # Select top visible frame, matching observed scroll behavior.
            top = [r for r in rects if r.y_depth == self.scroll]
            if top:
                top.sort(key=lambda r: r.x)
                self.selected = top[0].node
                self.cursor_x = top[0].x
            return

        cur = rect_for_node(rects, self.selected)
        if cur is None:
            self.selected = self.zoom
            cur = rect_for_node(rects, self.selected)
        if cur is None:
            return
        if self.cursor_x is None:
            self.cursor_x = width // 2

        if key in ("h", "l"):
            row = sorted([r for r in rects if r.y_depth == cur.y_depth], key=lambda r: r.x)
            try:
                idx = next(i for i, r in enumerate(row) if r.node is self.selected)
            except StopIteration:
                idx = 0
            if key == "h" and idx > 0:
                self.selected = row[idx - 1].node
                self.cursor_x = row[idx - 1].x
            elif key == "l" and idx + 1 < len(row):
                self.selected = row[idx + 1].node
                self.cursor_x = row[idx + 1].x
            return

        if key in ("j", "k"):
            target_depth = cur.y_depth + (1 if key == "j" else -1)
            row = sorted([r for r in rects if r.y_depth == target_depth], key=lambda r: r.x)
            if not row:
                return
            x = self.cursor_x
            chosen = None
            for r in row:
                if r.x <= x < r.x + r.w:
                    chosen = r
                    break
            if chosen is None:
                # choose nearest frame when the cursor is in a gap/outside.
                chosen = min(row, key=lambda r: min(abs(x - r.x), abs(x - (r.x + r.w - 1))))
            self.selected = chosen.node
            # After vertical movement, the original behaves as if the horizontal
            # cursor snaps to the frame's left edge.
            self.cursor_x = chosen.x
            self.ensure_selected_visible(rects, flame_rows)
            return


def render(state: UIState, use_color: bool = True) -> str:
    size = shutil.get_terminal_size((80, 24))
    width, height = max(1, size.columns), max(1, size.lines)
    flame_start, flame_rows, bottom_start = state.visible_rows_count(height)
    rects = state.current_rects(width)
    state.ensure_selected_visible(rects, flame_rows)

    lines = [" " * width for _ in range(height)]
    if height >= 1:
        lines[0] = separator(width)
    if height >= 2:
        lines[1] = header_line(width, state.source)
    header_rows = 3 if height >= 13 else 2
    if header_rows == 3 and height >= 3:
        lines[2] = separator(width)

    # Draw flamegraph rows.  Use ANSI cursor positioning to allow colored spans.
    # For the in-memory line fallback we store plain text; colored output is
    # appended later as positioned fragments.
    color_fragments: List[Tuple[int, int, str]] = []  # row0, col0, ansi text
    for r in rects:
        row0 = (flame_start - 1) + (r.y_depth - state.scroll)
        if row0 < 0 or row0 >= min(height, bottom_start - 1):
            continue
        if r.w <= 0 or r.x >= width:
            continue
        w = min(r.w, width - r.x)
        text = (" " + r.node.name)[:w].ljust(w)
        # Plain tmux captures are driven by the terminal emulator after ANSI, but
        # keeping lines accurate helps if colors are disabled.
        line = list(lines[row0])
        put_text(line, r.x, text)
        lines[row0] = "".join(line)
        if use_color:
            color_fragments.append((row0, r.x, colorize_frame(text, r.node, r.node is state.selected, state.matching(r.node), state.root)))

    # Bottom information blocks.
    row = bottom_start - 1
    def add_block(title: str, body: str) -> None:
        nonlocal row
        if row < height:
            lines[row] = separator(width, title)
        row += 1
        if row < height:
            lines[row] = trunc(body, width).ljust(width)
        row += 1

    if state.search_mode:
        add_block("Search", state.search_input)
    elif state.match_query is not None:
        detail = f'"{state.match_query}" [{state.match_samples} samples, {pct_str(state.match_samples, state.root.value)}% of all]'
        add_block("Match", detail)

    add_block("Selected", node_detail(state.selected, state.root, state.zoom))

    if state.info:
        add_block("Info", state.info)

    if state.debug:
        add_block("Debug", "Debug: flamegraph:0.02ms")

    if row < height:
        lines[row] = separator(width)
        row += 1
    if row < height:
        lines[row] = trunc(FOOTER, width).ljust(width)

    # Construct a full-screen draw.  Start with reset/no-wrap-ish clear.  Lines
    # without colors are printed row by row, then colored flame fragments overlay
    # their spans, matching the visible text in terminal captures.
    out: List[str] = ["\x1b[2J\x1b[1;1H"]
    out.append("\r\n".join(lines))
    if use_color and color_fragments:
        for row0, col0, frag in color_fragments:
            out.append(f"\x1b[{row0+1};{col0+1}H{frag}")
        out.append("\x1b[39m\x1b[49m")
    out.append("\x1b[?25l")
    return "".join(out)


# ---------------------------------------------------------------------------
# Terminal IO/event loop

class Terminal:
    def __init__(self) -> None:
        self.out = sys.stdout
        self.key_file = None
        self.fd: Optional[int] = None
        self.old_attrs = None

    def open(self) -> bool:
        # Prefer /dev/tty so piped folded data can still be controlled from the
        # terminal, as observed inside tmux.
        try:
            self.key_file = open("/dev/tty", "rb", buffering=0)
            self.fd = self.key_file.fileno()
        except OSError:
            if sys.stdin.isatty():
                self.fd = sys.stdin.fileno()
                self.key_file = sys.stdin.buffer
            else:
                return False
        try:
            if self.fd is not None and os.isatty(self.fd):
                self.old_attrs = termios.tcgetattr(self.fd)
                tty.setcbreak(self.fd)
        except Exception:
            pass
        self.write("\x1b[?1049h\x1b[?25l")
        return True

    def close(self) -> None:
        try:
            self.write("\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l")
            self.write("\x1b[?1049l\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h")
        finally:
            if self.old_attrs is not None and self.fd is not None:
                try:
                    termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old_attrs)
                except Exception:
                    pass
            if self.key_file is not None and self.key_file is not sys.stdin.buffer:
                try:
                    self.key_file.close()
                except Exception:
                    pass

    def write(self, s: str) -> None:
        self.out.write(s)
        self.out.flush()

    def read_key(self) -> str:
        if self.fd is None:
            return ""
        # Blocking wait for one byte.
        while True:
            r, _, _ = select.select([self.fd], [], [], None)
            if self.fd in r:
                break
        try:
            b = os.read(self.fd, 1)
        except OSError:
            return ""
        if not b:
            time.sleep(0.05)
            return ""
        c = b[0]
        if c == 3:
            return "CTRL_C"
        if c in (10, 13):
            return "ENTER"
        if c in (8, 127):
            return "BACKSPACE"
        if c == 27:
            # Escape sequence or bare Escape.  Collect immediately available
            # bytes; cbreak mode leaves arrow keys as ESC [ X.
            seq = b""
            end = time.time() + 0.03
            while time.time() < end:
                r, _, _ = select.select([self.fd], [], [], max(0, end - time.time()))
                if self.fd not in r:
                    break
                try:
                    chunk = os.read(self.fd, 1)
                except OSError:
                    break
                if not chunk:
                    break
                seq += chunk
                if len(seq) >= 2 and seq[-1:] in b"ABCD~":
                    break
            if seq == b"[A":
                return "k"
            if seq == b"[B":
                return "j"
            if seq == b"[C":
                return "l"
            if seq == b"[D":
                return "h"
            return "ESC"
        try:
            return bytes([c]).decode("utf-8")
        except UnicodeDecodeError:
            return ""


def run_tui(profile: Profile, source: str, args: Args) -> int:
    state = UIState(profile=profile, source=source, sorted=args.sorted, debug=args.debug)
    term = Terminal()
    if not term.open():
        sys.stderr.write(NON_TTY_ERROR)
        return 1

    interrupted = False
    try:
        while True:
            term.write(render(state, use_color=True))
            key = term.read_key()
            size = shutil.get_terminal_size((80, 24))
            width, height = max(1, size.columns), max(1, size.lines)
            if not key:
                continue
            if key == "CTRL_C" or (not state.search_mode and key == "q"):
                break

            if state.search_mode:
                if key == "ENTER":
                    q = state.search_input
                    state.search_mode = False
                    state.search_input = ""
                    state.update_matches(q)
                elif key == "ESC":
                    state.search_mode = False
                    state.search_input = ""
                elif key == "BACKSPACE":
                    state.search_input = state.search_input[:-1]
                elif len(key) == 1 and key >= " ":
                    state.search_input += key
                continue

            if key in ("h", "j", "k", "l", "f", "b", "g", "G"):
                state.navigate(key, width, height)
            elif key == "ENTER":
                state.set_zoom()
            elif key == "ESC":
                state.clear_zoom()
            elif key == "r":
                state.reset_view()
            elif key == "/":
                state.search_mode = True
                state.search_input = ""
                state.info = None
            elif key == "#":
                if state.selected is not state.root:
                    query = "^" + re.escape(state.selected.name) + "$"
                    state.update_matches(query)
            elif key == "n":
                state.next_match(False)
            elif key == "N":
                state.next_match(True)
            else:
                # z and unrecognized keys are ignored (z matters only for live mode,
                # which this observed CLI does not expose).
                pass
    finally:
        term.close()
    return 0


# ---------------------------------------------------------------------------

def main(argv: List[str]) -> int:
    try:
        args = parse_args(argv)
    except CliExit as e:
        if e.stdout:
            sys.stdout.write(e.stdout)
        if e.stderr:
            sys.stderr.write(e.stderr)
        return e.code

    try:
        data, source = read_profile(args)
    except OSError as e:
        return panic_read_file(e)

    if args.echo:
        sys.stdout.write(data)
        sys.stdout.flush()

    profile = parse_folded(data)
    return run_tui(profile, source, args)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try:
            sys.stderr.close()
        finally:
            os._exit(1)
