def main(argv: List[str]) -> int:
    try:
        args = parse_args(argv)
    except CliExit as e:
        if e.stdout:
            sys.stdout.write(e.stdout)
        if e.stderr:
            sys.stderr.write(e.stderr)
        return e.code

    try:
        data, source = read_profile(args)
    except OSError as e:
        return panic_read_file(e)

    if args.echo:
        sys.stdout.write(data)
        sys.stdout.flush()

    profile = parse_folded(data)
    return run_tui(profile, source, args)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try:
            sys.stderr.close()
        finally:
            os._exit(1)
